cat > lexer.ts <<'E'
import type { LogoError } from "./types";

export type TokKind = "num" | "word" | "lbr" | "rbr";
export interface Token {
  kind: TokKind;
  text: string;
  value: number;
  line: number;
  col: number;
  spaceBefore: boolean;
  spaceAfter: boolean;
}

export class LogoFail extends Error {
  constructor(public info: LogoError) { super(info.message); }
}
export const fail = (message: string, t: { line: number; col: number }): never => {
  throw new LogoFail({ message, line: t.line, column: t.col });
};

export function lex(src: string): Token[] {
  const toks: Token[] = [];
  let i = 0, line = 1, col = 1;
  const adv = (n: number) => { i += n; col += n; };
  while (i < src.length) {
    const c = src[i];
    if (c === "\n") { i++; line++; col = 1; continue; }
    if (/\s/.test(c)) { adv(1); continue; }
    if (c === ";") { while (i < src.length && src[i] !== "\n") adv(1); continue; }
    const start = { line, col };
    let m: RegExpMatchArray | null;
    if ((m = src.slice(i).match(/^(\d+(\.\d+)?|\.\d+)/))) {
      toks.push({ kind: "num", text: m[0], value: Number(m[0]), ...start, spaceBefore: false, spaceAfter: false });
      adv(m[0].length);
    } else if ((m = src.slice(i).match(/^[\p{L}_][\p{L}\p{N}_]*/u))) {
      toks.push({ kind: "word", text: m[0], value: 0, ...start, spaceBefore: false, spaceAfter: false });
      adv(m[0].length);
    } else if (c === "[" || c === "]") {
      toks.push({ kind: c === "[" ? "lbr" : "rbr", text: c, value: 0, ...start, spaceBefore: false, spaceAfter: false });
      adv(1);
    } else fail(`Nieoczekiwany znak „${c}”`, start);
  }
  return toks;
}
E
cat > parser.ts <<'E'
import { lex, fail, type Token } from "./lexer";
import type { Mode } from "./types";

export type Stmt =
  | { op: "move"; sign: 1 | -1; arg: number; tok: Token }
  | { op: "turn"; sign: 1 | -1; arg: number; tok: Token }
  | { op: "repeat"; count: number; body: Stmt[]; tok: Token };

export function parse(src: string, _mode: Mode): Stmt[] {
  const toks = lex(src);
  let p = 0;
  const num = (cmd: Token): number => {
    const t = toks[p];
    if (!t || t.kind !== "num") return fail("Brakuje argumentu", t ?? cmd);
    p++;
    return t.value;
  };
  const block = (until: boolean): Stmt[] => {
    const out: Stmt[] = [];
    while (p < toks.length) {
      const t = toks[p];
      if (t.kind === "rbr") { if (until) return out; fail("Nadmiarowy nawias ]", t); }
      p++;
      const w = t.text.toLowerCase();
      if (w === "np") out.push({ op: "move", sign: 1, arg: num(t), tok: t });
      else if (w === "pw") out.push({ op: "turn", sign: 1, arg: num(t), tok: t });
      else if (w === "powtorz") {
        const count = num(t);
        const lb = toks[p];
        if (!lb || lb.kind !== "lbr") fail("Oczekiwano [", lb ?? t);
        p++;
        out.push({ op: "repeat", count, body: block(true), tok: t });
        p++;
      } else fail(`Nieznane polecenie „${t.text}”`, t);
    }
    if (until) fail("Brakuje ]", toks[toks.length - 1]);
    return out;
  };
  return block(false);
}
E
cat > exec.ts <<'E'
import type { Stmt } from "./parser";
import type { Segment, Vec } from "./types";

export function* execute(prog: Stmt[], segments: Segment[]): Generator<void> {
  let pos: Vec = [0, 0, 0];
  let h: Vec = [0, 1, 0], r: Vec = [1, 0, 0];
  function* go(body: Stmt[]): Generator<void> {
    for (const s of body) {
      if (s.op === "move") {
        const to = pos.map((v, k) => v + h[k] * s.arg * s.sign) as Vec;
        segments.push({ from: pos, to, color: "#16866a", width: 3 });
        pos = to;
      } else if (s.op === "turn") {
        const a = (s.arg * s.sign * Math.PI) / 180;
        const c = Math.round(Math.cos(a) * 1e12) / 1e12, sn = Math.round(Math.sin(a) * 1e12) / 1e12;
        const nh = h.map((v, k) => v * c + r[k] * sn) as Vec;
        const nr = r.map((v, k) => v * c - h[k] * sn) as Vec;
        h = nh; r = nr;
      } else for (let i = 0; i < s.count; i++) yield* go(s.body);
      yield;
    }
  }
  yield* go(prog);
}
E
cat > interpreter.ts <<'E'
import { parse } from "./parser";
import { execute } from "./exec";
import { LogoFail } from "./lexer";
import type { Mode, RunResult, Segment } from "./types";

export function run(source: string, mode: Mode): RunResult {
  const segments: Segment[] = [];
  try {
    const prog = parse(source, mode);
    for (const _ of execute(prog, segments));
    return { segments, error: null };
  } catch (e) {
    if (e instanceof LogoFail) return { segments, error: e.info };
    throw e;
  }
}
E
