import type { Expr, ExprNode, Stmt } from "./parser";
import type { Segment, Vec } from "./types";

function evalNode(n: ExprNode, at: Expr): number {
  let v: number;
  if (n.k === "num") return n.v;
  if (n.k === "neg") v = -evalNode(n.e, at);
  else {
