  let pos: Vec = [0, 0, 0];
  let h: Vec = [0, 1, 0], r: Vec = [1, 0, 0];
  let down = true, color = "#16866a", width = 3;
  const norm = (v: number) => Math.round(v * 1e12) / 1e12 + 0;
  function* go(body: Stmt[]): Generator<void> {
