      if (s.op === "move") {
        const d = ev(s.arg) * s.sign;
        const to = pos.map((v, k) => norm(v + h[k] * d)) as Vec;
        if (down && to.some((v, k) => v !== pos[k])) segments.push({ from: pos, to, color, width });
