      } else if (s.op === "turn") {
        const a = (ev(s.arg) * s.sign * Math.PI) / 180;
        const c = Math.cos(a), sn = Math.sin(a);
        const nh = h.map((v, k) => norm(v * c + r[k] * sn)) as Vec;
        const nr = r.map((v, k) => norm(v * c - h[k] * sn)) as Vec;
