export type TokKind = "num" | "word" | "str" | "lbr" | "rbr" | "lpar" | "rpar" | "op" | "cmp" | "comma" | "ma";
export interface Token {
  kind: TokKind;
  text: string;
  value: number;
  line: number;
  col: number;
  /** `:name` legacy form */
  colon?: boolean;
  spaceBefore: boolean;
  spaceAfter: boolean;
}

export class LogoFail extends Error {
  constructor(public info: LogoError) { super(info.message); }
}
export const fail = (message: string, t: { line: number; col: number }): never => {
  throw new LogoFail({ message, line: t.line, column: t.col });
};

export const MAX_CHARS = 50000;
export const MAX_TOKENS = 10000;

export function lex(src: string): Token[] {
  const toks: Token[] = [];
  const starts: number[] = [];
  const ends: number[] = [];
  let i = 0, line = 1, col = 1;
  const adv = (n: number) => { i += n; col += n; };
  if (src.length > MAX_CHARS) {
    const before = src.slice(0, MAX_CHARS).split("\n");
    fail(`Program jest zbyt długi (limit ${MAX_CHARS} znaków)`, { line: before.length, col: before[before.length - 1].length + 1 });
  }
  const push = (kind: TokKind, text: string, extra: Partial<Token> = {}) => {
    const t: Token = { kind, text, value: 0, line, col, spaceBefore: false, spaceAfter: false, ...extra };
    if (toks.length >= MAX_TOKENS) fail(`Program ma zbyt wiele symboli (limit ${MAX_TOKENS})`, t);
    toks.push(t);
    starts.push(i);
    ends.push(i + text.length);
    adv(text.length);
  };
  while (i < src.length) {
    const c = src[i];
    if (c === "\n") { i++; line++; col = 1; continue; }
    if (/\s/.test(c)) { adv(1); continue; }
    if (c === ";") { while (i < src.length && src[i] !== "\n") adv(1); continue; }
    const rest = src.slice(i, i + 400);
    let m: RegExpMatchArray | null;
    if ((m = rest.match(/^(\d+(\.\d+)?|\.\d+)/))) {
      if (/^[\p{L}\p{N}_.]/u.test(src[i + m[0].length] ?? "")) fail(`Nieprawidłowa liczba „${rest.match(/^[\p{L}\p{N}_.]+/u)![0]}”`, { line, col });
      push("num", m[0], { value: Number(src.slice(i).match(/^(\d+(\.\d+)?|\.\d+)/)![0]) });
    } else if (c === ":" && (m = rest.match(/^:([\p{L}_][\p{L}\p{N}_]*)/u))) {
      push("word", m[0], { colon: true });
    } else if ((m = rest.match(/^[\p{L}_][\p{L}\p{N}_]*/u))) {
      const word = src.slice(i).match(/^[\p{L}\p{N}_]+/u)![0];
