      if (e < 0 || (nl >= 0 && nl < e)) fail("Niedomknięty napis", { line, col });
      push("str", src.slice(i, e + 1));
    } else if (c === "[") push("lbr", c);
    else if (c === "]") push("rbr", c);
    else if (c === "(") push("lpar", c);
    else if (c === ")") push("rpar", c);
    else if (c === ",") push("comma", c);
    else if ("+-*/".includes(c)) push("op", c);
    else if ((m = rest.match(/^(<=|>=|<>|<|>|=)/))) push("cmp", m[0]);
