    t.spaceBefore = k === 0 || /\s|;/.test(src[starts[k] - 1] ?? " ") || (src[starts[k] - 1] === undefined) || ends[k - 1] !== starts[k];
    t.spaceAfter = k === toks.length - 1 || starts[k + 1] !== ends[k];
