cat >> test/interpreter.test.ts <<'E'

test("variables, :name legacy form and nrpowt (innermost repeat) feed expressions", () => {
  expect(lastY("niech x 5 np x")).toBe(5);
  expect(lastY("niech x 5 niech x x + 1 np :X")).toBe(6);
  const r = run("powtorz 3 [np nrpowt]", "2d");
  expect(r.segments.map((s) => s.to[1])).toEqual([1, 3, 6]);
  const n = run("powtorz 2 [powtorz 3 [np REPCOUNT] np nrpowt]", "2d");
  expect(n.segments.map((s) => s.to[1])).toEqual([1, 3, 6, 7, 8, 10, 13, 15]);
});

test("conditions compare exactly and choose a branch", () => {
  expect(run("jeśli 0.1 + 0.2 = 0.3 [np 10]", "2d")).toEqual({ segments: [], error: null });
  expect(lastY("jesli 1 < 2 [np 3]")).toBe(3);
  expect(lastY("jeżeli 2 <> 2 [np 1] [np 2]")).toBe(2);
  expect(lastY("ifelse 2 >= 2 [np 1] [np 2]")).toBe(1);
  expect(lastY("if 3 <= 2 [np 1] np 4")).toBe(4);
  expect(lastY("niech z 1 powtorz 4 [jeżeli z > 0 [np 1] [np 2] niech z -z]")).toBe(6);
});

test("name errors: unknown name and nrpowt outside a repeat are parse-time; unassigned is run-time", () => {
  expect(run("np 1\nnp y", "2d")).toEqual({ segments: [], error: { message: expect.any(String), line: 2, column: 4 } });
  expect(run("np 1\nnp nrpowt", "2d")).toMatchObject({ segments: [], error: { line: 2, column: 4 } });
  const u = run("np 5\nnp z + 1\nniech z 1", "2d");
  expect(u.segments.length).toBe(1);
  expect(u.error).toMatchObject({ line: 2, column: 4 });
  expect(run("niech np 5", "2d").error).toMatchObject({ line: 1, column: 7 });
  const w = run("np 5 niech w 20 grubosc w", "2d");
  expect(w.segments.length).toBe(1);
  expect(w.error).toMatchObject({ line: 1, column: 25 });
});
E
bun test 2>&1 | grep -E "^\(fail|pass|fail"

