import { fail, type Token } from "./lexer";
import { ev, checkWidth, checkCount, type Scope } from "./eval";
import type { Program, Stmt } from "./parser";
import type { Segment, Vec } from "./types";

export const MAX_OPS = 10000;
export const MAX_FRAMES = 32;
export const MAX_SEGMENTS = 10000;
export const MAX_COORD = 100000;

const cosd = (d: number) => (d % 90 === 0 ? [1, 0, -1, 0][(((d / 90) % 4) + 4) % 4] : Math.cos((d * Math.PI) / 180));
const sind = (d: number) => (d % 90 === 0 ? [0, 1, 0, -1][(((d / 90) % 4) + 4) % 4] : Math.sin((d * Math.PI) / 180));
const norm = (v: number) => Math.round(v * 1e12) / 1e12 + 0;

export interface Turtle { pos: Vec; heading: Vec; right: Vec; up: Vec; down: boolean; color: string; width: number }

/** One `next()` performs one command and yields the token that was executed. */
export function createExecution(program: Program, segments: Segment[]) {
  const t: Turtle = { pos: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1], down: true, color: "#16866a", width: 3 };
  const globals = new Map<string, number>();
  interface Frame { locals: Map<string, number> | null; reps: number[] }
  let cur: Frame = { locals: null, reps: [] };
  const sc: Scope = {
    lookup: (n) => cur.locals?.get(n) ?? globals.get(n),
    rep: () => cur.reps[cur.reps.length - 1],
  };
  let ops = 0;
  let frames = 0;
  const tick = (tok: Token) => { if (++ops > MAX_OPS) fail(`Przekroczono limit ${MAX_OPS} wykonanych operacji`, tok); };
  const enter = (tok: Token) => { if (++frames > MAX_FRAMES) fail(`Przekroczono limit ${MAX_FRAMES} jednocześnie aktywnych wywołań i powtórzeń`, tok); };

  const draw = (to: Vec, tok: Token) => {
    if (to.some((v) => Math.abs(v) > MAX_COORD)) fail(`Współrzędne wychodzą poza zakres ±${MAX_COORD}`, tok);
    if (t.down && to.some((v, k) => v !== t.pos[k])) {
      if (segments.length >= MAX_SEGMENTS) fail(`Przekroczono limit ${MAX_SEGMENTS} odcinków`, tok);
      segments.push({ from: [...t.pos], to: [...to], color: t.color, width: t.width });
    }
    t.pos = to;
  };

  function* go(body: Stmt[]): Generator<Token, boolean> {
    for (const s of body) {
      tick(s.tok);
      switch (s.op) {
        case "move": {
          const d = ev(s.arg, sc) * s.sign;
          draw(t.pos.map((v, k) => norm(v + t.heading[k] * d)) as Vec, s.tok);
          break;
        }
        case "turn": case "pitch": case "roll": {
          const deg = ev(s.arg, sc) * s.sign;
          const c = cosd(deg), sn = sind(deg);
          // rotate the pair (a, b) so that a moves towards b
          const rot = (a: Vec, b: Vec): [Vec, Vec] => [
            a.map((v, k) => norm(v * c + b[k] * sn)) as Vec,
            b.map((v, k) => norm(v * c - a[k] * sn)) as Vec,
          ];
          if (s.op === "turn") [t.heading, t.right] = rot(t.heading, t.right);
          else if (s.op === "pitch") [t.heading, t.up] = rot(t.heading, t.up);
          else [t.up, t.right] = rot(t.up, t.right);
          break;
        }
        case "home":
          draw([0, 0, 0], s.tok);
          t.heading = [0, 1, 0]; t.right = [1, 0, 0]; t.up = [0, 0, 1];
          break;
        case "clear": segments.length = 0; break;
        case "pen": t.down = s.down; break;
        case "color": t.color = s.value; break;
        case "width": t.width = checkWidth(ev(s.arg, sc), s.arg); break;
        case "let": (cur.locals ?? globals).set(s.name, ev(s.arg, sc)); break;
        case "stop": yield s.tok; return true;
        case "call": {
          const proc = program.procs.get(s.proc)!;
          const locals = new Map<string, number>();
          proc.params.forEach((n, i) => locals.set(n, ev(s.args[i], sc)));
          enter(s.tok);
          yield s.tok;
          const saved = cur;
          cur = { locals, reps: [] };
          yield* go(proc.body);
          cur = saved;
          frames--;
          tick(s.tok);
          continue;
        }
        case "if": {
          const l = ev(s.l, sc), rv = ev(s.r, sc);
          const ok = { "<": l < rv, ">": l > rv, "=": l === rv, "<=": l <= rv, ">=": l >= rv, "<>": l !== rv }[s.cmp];
          yield s.tok;
          const b = ok ? s.then : s.else;
          if (b) {
            if (yield* go(b)) return true;
            tick(s.tok);
          }
          continue;
        }
        case "repeat": {
          const n = checkCount(ev(s.count, sc), s.count);
          enter(s.tok);
          yield s.tok;
          cur.reps.push(0);
          for (let i = 1; i <= n; i++) {
            cur.reps[cur.reps.length - 1] = i;
            if (yield* go(s.body)) return true;
            tick(s.tok);
          }
          cur.reps.pop();
          frames--;
          continue;
        }
      }
      yield s.tok;
    }
    return false;
  }
  return { turtle: t, steps: go(program.main) as Generator<Token, boolean> };
}
