import { test, expect } from "bun:test";
import { EXAMPLES } from "../src/examples";
import { run } from "../src/lang/interpreter";

// Segment totals counted by hand from each program's loops (independent of the interpreter).
const EXPECTED: Record<string, [string, number]> = {
  kwadrat: ["2d", 4], gwiazda: ["2d", 5], rozeta: ["2d", 48], spirala: ["2d", 90],
  wielokaty: ["2d", 3 + 4 + 5 + 6 + 7 + 8 + 9], drzewo: ["2d", 255], sniezynka: ["2d", 3 * 4 ** 4],
  schody: ["3d", 12], szescian: ["3d", 4 + 1 + 4 + 4 * 2], pierscien: ["3d", 36], kula: ["3d", 12 * 36],
  helisa: ["3d", 240], drzewo3d: ["3d", -1],
};

test("the thirteen standard programs are shipped under their ids and modes", () => {
  expect(EXAMPLES.map((e) => [e.id, e.mode])).toEqual(Object.entries(EXPECTED).map(([id, [m]]) => [id, m]));
  expect(EXAMPLES.find((e) => e.id === "kwadrat")!.source).toBe(`; Cztery boki, cztery skręty.
kolor "#16866a"
grubosc 3
powtorz 4 [
  np 120
  pw 90
]`);
});

test("every standard program runs without error and draws the expected number of segments", () => {
  for (const e of EXAMPLES) {
    const r = run(e.source, e.mode);
    expect([e.id, r.error]).toEqual([e.id, null]);
    const want = EXPECTED[e.id][1];
    if (want >= 0) expect([e.id, r.segments.length]).toEqual([e.id, want]);
    else expect(r.segments.length).toBeGreaterThan(0);
  }
});

test("Spirala alternates colours and Szescian closes into a unit cube of edge 100", () => {
  const sp = run(EXAMPLES.find((e) => e.id === "spirala")!.source, "2d").segments;
  expect([sp[0].color, sp[1].color, sp[2].color]).toEqual(["#16866a", "#c1763d", "#16866a"]);
  const cube = run(EXAMPLES.find((e) => e.id === "szescian")!.source, "3d").segments;
  const pts = cube.flatMap((s) => [s.from, s.to]);
  const ext = (k: number) => [Math.min(...pts.map((p) => p[k])), Math.max(...pts.map((p) => p[k]))];
  expect([ext(0), ext(1), ext(2)]).toEqual([[0, 100], [0, 100], [0, 100]]);
});
