import { compile, createExecution } from "../lang/interpreter";
import { LogoFail } from "../lang/lexer";
import type { Turtle } from "../lang/exec";
import type { LogoError, Mode, Segment } from "../lang/types";

export interface Scheduler { set(fn: () => void, ms: number): unknown; clear(handle: unknown): void }
export type Status = "idle" | "running" | "paused" | "finished" | "error";

export interface ViewTurtle { pos: [number, number, number]; heading: [number, number, number]; right: [number, number, number]; up: [number, number, number]; down: boolean; color: string }
export interface ControllerState {
  status: Status;
  mode: Mode;
  segments: Segment[];
  turtle: ViewTurtle;
  /** 1-based line being executed, or null */
  line: number | null;
  error: LogoError | null;
}

const HOME = (): ViewTurtle => ({ pos: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1], down: true, color: "#16866a" });

export class Controller {
  state: ControllerState = { status: "idle", mode: "2d", segments: [], turtle: HOME(), line: null, error: null };
  private source = "";
  private exec: { turtle: Turtle; steps: Generator<{ line: number }, boolean> } | null = null;
  private segments: Segment[] = [];
  private timer: unknown = null;
  private listeners = new Set<() => void>();

  constructor(private scheduler: Scheduler = { set: (f, ms) => setTimeout(f, ms), clear: (h) => clearTimeout(h as number) }) {}

  subscribe(fn: () => void) { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  private emit() { this.listeners.forEach((f) => f()); }

  load(source: string, mode: Mode) {
    this.source = source;
    this.state.mode = mode;
    this.reset();
  }

  /** Prepares a fresh execution; returns false on a parse-time error. */
  private start(): boolean {
    this.reset();
    const c = compile(this.source, this.state.mode);
    if (c.error) { this.state = { ...this.state, status: "error", error: c.error, line: null }; this.emit(); return false; }
    this.segments = [];
    this.exec = createExecution(c.program, this.segments) as any;
    return true;
  }

  private advance(): boolean {
    const ex = this.exec!;
    try {
      const r = ex.steps.next();
      if (r.done) { this.finish("finished", null); return false; }
      this.state.line = r.value.line;
      this.sync();
      return true;
    } catch (e) {
      if (!(e instanceof LogoFail)) throw e;
      this.sync();
      this.finish("error", e.info);
      return false;
    }
  }

  private sync() {
    const t = this.exec!.turtle;
    this.state = { ...this.state, segments: [...this.segments], turtle: { pos: [...t.pos], heading: [...t.heading], right: [...t.right], up: [...t.up], down: t.down, color: t.color } };
  }

  private finish(status: "finished" | "error", error: LogoError | null) {
    this.exec = null;
    this.sync2();
    this.state = { ...this.state, status, error, line: error ? error.line : null };
    this.emit();
  }
  private sync2() { /* state already synced by advance */ }

  step() {
    if (!this.exec && !this.start()) return;
    this.cancelTimer();
    if (this.advance()) this.state = { ...this.state, status: "paused" };
    this.emit();
  }

  reset() {
    this.cancelTimer();
    this.exec = null;
    this.segments = [];
    this.state = { ...this.state, status: "idle", segments: [], turtle: HOME(), line: null, error: null };
    this.emit();
  }

  private cancelTimer() { if (this.timer !== null) this.scheduler.clear(this.timer); this.timer = null; }
}
