    brief: "Narysuj krzyż złożony z czterech ramion o długości 80, wychodzących z punktu (0, 0) w górę, w prawo, w dół i w lewo.",
    hint: "Idź naprzód, wróć wstecz o tyle samo i skręć o 90 stopni.",
    solution: "powtorz 4 [np 80 ws 80 pw 90]",
  },
  {
    id: "schodki", title: "Schodki", mode: "2d", tolerance: 3,
    brief: "Narysuj pięć stopni schodów: każdy to 30 w górę, potem 30 w prawo. Zacznij w (0, 0).",
    hint: "Wewnątrz powtórz: krok, skręt w prawo, krok, skręt w lewo.",
    solution: "powtorz 5 [np 30 pw 90 np 30 lw 90]",
  },
  {
    id: "szescian", title: "Sześcian 80", mode: "3d", tolerance: 3,
    brief: "Narysuj w 3D szkielet sześcianu o krawędzi 80. Jeden wierzchołek leży w (0, 0, 0), a sześcian rośnie w stronę +X, +Y i +Z.",
    hint: "Dwa kwadraty, jeden nad drugim, połączone czterema pionowymi krawędziami. Użyj gora i dol.",
    solution: `powtorz 4 [np 80 pw 90]
gora 90 np 80 dol 90
powtorz 4 [np 80 pw 90]
powtorz 4 [
  np 80
  dol 90 np 80
  pod ws 80 opu
  gora 90 pw 90
]`,
  },
  {
    id: "okrag3d", title: "Pionowy okrąg", mode: "3d", tolerance: 4,
    brief: "Narysuj w 3D okrąg z 36 odcinków po 10, leżący w pionowej płaszczyźnie (X, Z) i zaczynający się w punkcie (0, 0, 0) w górę.",
    hint: "Najpierw podnieś nos żółwia o 90 stopni, potem 36 razy krok i skręt o 10 stopni.",
    solution: "gora 90 powtorz 36 [np 10 pw 10]",
  },
];

export interface CheckResult { passed: boolean; reason: string }

type Seg = { a: Vec; b: Vec };

function distToSegment(p: Vec, s: Seg): number {
  const ab = [s.b[0] - s.a[0], s.b[1] - s.a[1], s.b[2] - s.a[2]];
  const ap = [p[0] - s.a[0], p[1] - s.a[1], p[2] - s.a[2]];
  const len2 = ab[0] ** 2 + ab[1] ** 2 + ab[2] ** 2;
  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / len2));
  return Math.hypot(ap[0] - t * ab[0], ap[1] - t * ab[1], ap[2] - t * ab[2]);
}

function samples(segs: Seg[], spacing: number, cap: number): Vec[] {
  const out: Vec[] = [];
  const total = segs.reduce((n, s) => n + Math.ceil(Math.hypot(s.b[0] - s.a[0], s.b[1] - s.a[1], s.b[2] - s.a[2]) / spacing) + 1, 0);
  const keep = Math.max(1, Math.ceil(total / cap));
  let k = 0;
  for (const s of segs) {
    const n = Math.max(1, Math.ceil(Math.hypot(s.b[0] - s.a[0], s.b[1] - s.a[1], s.b[2] - s.a[2]) / spacing));
    for (let i = 0; i <= n; i++) if (k++ % keep === 0) out.push([0, 1, 2].map((d) => s.a[d] + ((s.b[d] - s.a[d]) * i) / n) as Vec);
  }
  return out;
}

/** Fraction of `from`'s drawing that lies farther than `tol` from `to`'s drawing. */
function uncovered(from: Seg[], to: Seg[], tol: number): number {
  const pts = samples(from, tol, 4000);
  if (pts.length === 0) return 0;
  let bad = 0;
  for (const p of pts) if (!to.some((s) => distToSegment(p, s) <= tol)) bad++;
  return bad / pts.length;
}

const toSegs = (segments: Segment[]): Seg[] => segments.map((s) => ({ a: s.from, b: s.to }));
const SLACK = 0.01;

export function checkChallenge(id: string, source: string): CheckResult {
  const ch = CHALLENGES.find((c) => c.id === id);
  if (!ch) return { passed: false, reason: "Nieznane wyzwanie." };
  const got = run(source, ch.mode);
  if (got.error) return { passed: false, reason: `Błąd w programie (wiersz ${got.error.line}, kolumna ${got.error.column}): ${got.error.message}` };
  if (got.segments.length === 0) return { passed: false, reason: "Nic nie narysowano. Napisz program, który rysuje szukany kształt." };
  const want = toSegs(run(ch.solution, ch.mode).segments);
  const have = toSegs(got.segments);
  const missing = uncovered(want, have, ch.tolerance);
  if (missing > SLACK) return { passed: false, reason: `Brakuje części rysunku: około ${Math.round(missing * 100)}% szukanego kształtu nie jest narysowane (albo leży w złym miejscu).` };
  const extra = uncovered(have, want, ch.tolerance);
  if (extra > SLACK) return { passed: false, reason: `Rysunek zawiera zbędne linie: około ${Math.round(extra * 100)}% Twojego rysunku wykracza poza szukany kształt.` };
  return { passed: true, reason: "Zgadza się! Rysunek pokrywa się ze wzorem." };
}
