}

/** Fraction of `from`'s drawing that lies farther than `tol` from `to`'s drawing. */
function uncovered(from: Seg[], to: Seg[], tol: number): number {
  const pts = samples(from, tol, 4000);
  if (pts.length === 0) return 0;
  let bad = 0;
  for (const p of pts) if (!to.some((s) => distToSegment(p, s) <= tol)) bad++;
  return bad / pts.length;
}

const toSegs = (segments: Segment[]): Seg[] => segments.map((s) => ({ a: s.from, b: s.to }));
const SLACK = 0.01;

export function checkChallenge(id: string, source: string): CheckResult {
  const ch = CHALLENGES.find((c) => c.id === id);
  if (!ch) return { passed: false, reason: "Nieznane wyzwanie." };
  const got = run(source, ch.mode);
  if (got.error) return { passed: false, reason: `Błąd w programie (wiersz ${got.error.line}, kolumna ${got.error.column}): ${got.error.message}` };
  if (got.segments.length === 0) return { passed: false, reason: "Nic nie narysowano. Napisz program, który rysuje szukany kształt." };
  const want = toSegs(run(ch.solution, ch.mode).segments);
  const have = toSegs(got.segments);
  const missing = uncovered(want, have, ch.tolerance);
  if (missing > SLACK) return { passed: false, reason: `Brakuje części rysunku: około ${Math.round(missing * 100)}% szukanego kształtu nie jest narysowane (albo leży w złym miejscu).` };
  const extra = uncovered(have, want, ch.tolerance);
  if (extra > SLACK) return { passed: false, reason: `Rysunek zawiera zbędne linie: około ${Math.round(extra * 100)}% Twojego rysunku wykracza poza szukany kształt.` };
  return { passed: true, reason: "Zgadza się! Rysunek pokrywa się ze wzorem." };
}
