import { Controller, type Scheduler } from "./controller";
import { EXAMPLES } from "../examples";
import type { Mode } from "../lang/types";

const KEY = "logomocja:v1";

interface Draft { source: string; baseline: string }
interface Persisted {
  slot: string;
  drafts: Record<string, Draft>;
  backup: { slot: string; source: string } | null;
}

const starter = (mode: Mode) => EXAMPLES.find((e) => e.id === (mode === "2d" ? "kwadrat" : "schody"))!.source;

export class Workspace {
  readonly controller: Controller;
  private data: Persisted;

  constructor(private storage: Storage, scheduler?: Scheduler) {
    this.data = this.read();
    this.controller = new Controller(scheduler);
    this.controller.load(this.source, this.mode);
  }

  private read(): Persisted {
    const fresh: Persisted = {
      slot: "2d",
      drafts: { "2d": { source: starter("2d"), baseline: starter("2d") }, "3d": { source: starter("3d"), baseline: starter("3d") } },
      backup: null,
    };
    try {
      const raw = this.storage.getItem(KEY);
      if (raw) {
        const saved = JSON.parse(raw) as Persisted;
        return { ...fresh, ...saved, drafts: { ...fresh.drafts, ...saved.drafts } };
      }
    } catch { /* unreadable storage: start fresh */ }
    return fresh;
  }

  private save() {
    try { this.storage.setItem(KEY, JSON.stringify(this.data)); } catch { /* quota or private mode: drafts stay in memory */ }
  }

  get mode(): Mode { return this.data.slot === "3d" ? "3d" : "2d"; }
  get source(): string { return this.data.drafts[this.data.slot].source; }

  setMode(mode: Mode) {
    this.data.slot = mode;
    this.save();
    this.controller.load(this.source, mode);
  }

  edit(source: string) {
    this.data.drafts[this.data.slot].source = source;
    this.save();
    this.controller.edit(source);
  }

  private isDirty(slot: string) {
    const d = this.data.drafts[slot];
    return d.source.trim() !== "" && d.source !== d.baseline;
  }

  /** Returns "needs-confirmation" instead of replacing an edited draft, unless `discardDraft` is given. */
  loadExample(id: string, opts: { discardDraft?: boolean } = {}): "loaded" | "needs-confirmation" | "unknown" {
    const example = EXAMPLES.find((e) => e.id === id);
    if (!example) return "unknown";
    const slot = example.mode;
    if (this.isDirty(slot)) {
      if (!opts.discardDraft) return "needs-confirmation";
      this.data.backup = { slot, source: this.data.drafts[slot].source };
    }
    this.data.drafts[slot] = { source: example.source, baseline: example.source };
    this.setMode(slot);
    return "loaded";
  }

  /** Brings back the draft that the last confirmed example load replaced. */
  restoreBackup(): boolean {
    const b = this.data.backup;
    if (!b) return false;
    this.data.drafts[b.slot] = { source: b.source, baseline: this.data.drafts[b.slot].baseline };
    this.data.backup = null;
    this.setMode(b.slot as Mode);
    return true;
  }
}
