import { h } from "./dom";
import { colourOf, highlightLine, procedureNames } from "./highlight";
import type { LogoError } from "../lang/types";

/** Textarea with a highlighted overlay, a line-number gutter, an error marker and an executing-line band. */
export class Editor {
  readonly el: HTMLElement;
  private ta: HTMLTextAreaElement;
  private hl: HTMLElement;
  private gutter: HTMLElement;
  private gutterInner: HTMLElement;
  private line: number | null = null;
  private error: LogoError | null = null;
  private lines: string[] = [];
  onInput: (value: string) => void = () => {};

  constructor(describedBy?: string) {
    this.ta = h("textarea", {
      class: "ed-input", spellcheck: false, autocapitalize: "off", autocomplete: "off", autocorrect: "off", wrap: "off",
      "aria-label": "Kod programu Logo", "aria-describedby": describedBy, rows: 12,
    });
    this.hl = h("pre", { class: "ed-hl", "aria-hidden": "true" });
    this.gutterInner = h("div", { class: "ed-gutter-inner" });
    this.gutter = h("div", { class: "ed-gutter", "aria-hidden": "true" }, this.gutterInner);
    this.el = h("div", { class: "editor" }, this.gutter, h("div", { class: "ed-wrap" }, this.hl, this.ta));
    this.ta.addEventListener("input", () => { this.render(); this.onInput(this.ta.value); });
    this.ta.addEventListener("scroll", () => this.syncScroll());
    this.ta.addEventListener("keydown", (e) => {
      // Tab inserts indentation; Escape then Tab leaves the field, so keyboard users are never trapped.
      if (e.key === "Tab" && !e.shiftKey && !e.ctrlKey && !e.altKey && !this.tabEscape) {
        e.preventDefault();
        document.execCommand("insertText", false, "  ");
      } else if (e.key === "Escape") this.tabEscape = true;
      else this.tabEscape = false;
    });
    this.ta.addEventListener("blur", () => (this.tabEscape = false));
  }
  private tabEscape = false;

  get value() { return this.ta.value; }
  setValue(v: string) { this.ta.value = v; this.render(); }
  focus() { this.ta.focus(); }
  setCurrentLine(line: number | null) {
    if (line === this.line) return;
    this.line = line;
    this.render();
    if (line !== null) this.reveal(line);
  }
  setError(e: LogoError | null) { this.error = e; this.render(); if (e) this.reveal(e.line); }

  /** Scrolls the textarea so that a line is visible. */
  private reveal(line: number) {
    const lh = this.lineHeight();
    const top = (line - 1) * lh, bottom = line * lh;
    if (top < this.ta.scrollTop) this.ta.scrollTop = top;
    else if (bottom > this.ta.scrollTop + this.ta.clientHeight - lh) this.ta.scrollTop = bottom - this.ta.clientHeight + lh * 2;
  }
  private lineHeight() { return parseFloat(getComputedStyle(this.ta).lineHeight) || 21; }
  private syncScroll() {
    this.hl.style.transform = `translate(${-this.ta.scrollLeft}px, ${-this.ta.scrollTop}px)`;
    this.gutterInner.style.transform = `translateY(${-this.ta.scrollTop}px)`;
  }

  /** Re-renders the overlay; cheap enough for the 50,000 character limit. */
  private render() {
    const src = this.ta.value;
    this.lines = src.split("\n");
    const procs = procedureNames(src);
    const frag = document.createDocumentFragment();
    const nums = document.createDocumentFragment();
    this.lines.forEach((text, i) => {
      const n = i + 1;
      const row = h("div", { class: "ln" + (n === this.line ? " ln-run" : "") + (this.error?.line === n ? " ln-err" : "") });
      const err = this.error && this.error.line === n ? this.error : null;
      const start = err ? err.column - 1 : -1;
      const m = err ? text.slice(start).match(/^(?:[\p{L}\p{N}_.:"#]+|\S)/u) : null;
      const end = err ? start + (m ? m[0].length : 1) : -1;
      let at = 0;
      for (const p of highlightLine(text, procs)) {
        const pStart = at, pEnd = at + p.text.length;
        at = pEnd;
        const sw = p.cls === "t-col" ? colourOf(p.text) : null;
        // split the piece around the error range so the marker covers exactly the offending token
        const cuts = err ? [Math.max(pStart, start), Math.min(pEnd, end)] : [pEnd, pEnd];
        const overlap = err && cuts[0] < cuts[1];
        const parts: [string, boolean][] = overlap
          ? [[p.text.slice(0, cuts[0] - pStart), false], [p.text.slice(cuts[0] - pStart, cuts[1] - pStart), true], [p.text.slice(cuts[1] - pStart), false]]
          : [[p.text, false]];
        for (const [t, bad] of parts) if (t) row.appendChild(h("span", { class: p.cls + (bad ? " t-error" : ""), style: sw ? `--sw:${sw}` : undefined }, t));
      }
      if (err && start >= text.length) row.appendChild(h("span", { class: "t-error t-eol" }, " "));
      if (text === "") row.appendChild(document.createTextNode("​"));
      frag.appendChild(row);
      const num = h("div", { class: "gn" + (n === this.line ? " gn-run" : "") + (this.error?.line === n ? " gn-err" : "") }, String(n));
      nums.appendChild(num);
    });
    this.hl.replaceChildren(frag);
    this.gutterInner.replaceChildren(nums);
    this.gutter.style.minWidth = `${Math.max(3, String(this.lines.length).length + 2)}ch`;
    this.syncScroll();
  }
}
