export function procedureNames(source: string): Set<string> {
  const out = new Set<string>();
  for (const m of source.matchAll(/^[ \t]*(?:oto|to)[ \t]+([\p{L}_][\p{L}\p{N}_]*)/gimu)) out.add(m[1].toLowerCase());
  return out;
}

const RE = /(;.*)|("(?:[^"\n]*)"?)|(\d+(?:\.\d+)?|\.\d+)|(:?[\p{L}_][\p{L}\p{N}_]*:?)|([[\]])|([()])|(<=|>=|<>|[<>=+\-*/,])|(\s+)|(.)/gsu;

/** Splits one source line into classified pieces (the pieces always concatenate back to the line). */
export function highlightLine(line: string, procs: Set<string>): Piece[] {
  const out: Piece[] = [];
  for (const m of line.matchAll(RE)) {
    const [text, cmt, str, num, word, br, par, op] = m;
    let cls = "";
    if (cmt) cls = "t-cmt";
    else if (str) cls = /^"#[0-9a-fA-F]{6}"$/.test(str) ? "t-col" : "t-bad";
    else if (num) cls = "t-num";
    else if (word) {
      const w = word.toLowerCase();
      if (w === "ma:") cls = "t-def";
      else if (DEFINE.has(w)) cls = "t-def";
      else if (REPEAT_COUNTER_WORDS.includes(w)) cls = "t-rep";
      else if (!w.startsWith(":") && w in COMMAND_CANON) cls = "t-cmd";
      else if (procs.has(w)) cls = "t-proc";
      else cls = "t-name";
    } else if (br) cls = "t-br";
    else if (par) cls = "t-par";
    else if (op) cls = "t-op";
    out.push({ text, cls });
  }
  return out;
}

/** Colour literal value for a piece, used for a swatch underline. */
export const colourOf = (text: string) => (/^"#[0-9a-fA-F]{6}"$/.test(text) ? text.slice(1, -1) : null);
