export interface GestureHandlers {
  /** One-pointer drag. `pan` is true for shift / middle / right button. */
  drag(dx: number, dy: number, pan: boolean): void;
  /** Zoom by factor around a point in canvas CSS pixels. */
  zoom(factor: number, x: number, y: number): void;
  /** Two-finger pan. */
  pan(dx: number, dy: number): void;
  /** Arrow-key navigation: dx/dy in -1..1. */
  key(dx: number, dy: number, shift: boolean): void;
  reset(): void;
}

/** Mouse, touch, wheel and keyboard navigation for a canvas. */
export function attachGestures(canvas: HTMLCanvasElement, g: GestureHandlers) {
  const pts = new Map<number, { x: number; y: number }>();
  let panning = false;
  const local = (e: { clientX: number; clientY: number }) => {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  };
  const centroid = () => {
    const v = [...pts.values()];
    return { x: (v[0].x + v[1].x) / 2, y: (v[0].y + v[1].y) / 2, d: Math.hypot(v[0].x - v[1].x, v[0].y - v[1].y) };
  };
  canvas.addEventListener("pointerdown", (e) => {
    canvas.setPointerCapture(e.pointerId);
    pts.set(e.pointerId, local(e));
    panning = e.shiftKey || e.button === 1 || e.button === 2;
  });
  canvas.addEventListener("pointermove", (e) => {
    const prev = pts.get(e.pointerId);
    if (!prev) return;
    const cur = local(e);
    if (pts.size === 1) g.drag(cur.x - prev.x, cur.y - prev.y, panning);
    else if (pts.size === 2) {
      const before = centroid();
      pts.set(e.pointerId, cur);
      const after = centroid();
      g.pan(after.x - before.x, after.y - before.y);
      if (before.d > 0 && after.d > 0) g.zoom(after.d / before.d, after.x, after.y);
    }
    pts.set(e.pointerId, cur);
  });
  const up = (e: PointerEvent) => { pts.delete(e.pointerId); };
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", up);
  canvas.addEventListener("contextmenu", (e) => e.preventDefault());
  canvas.addEventListener("wheel", (e) => {
    e.preventDefault();
    const p = local(e);
    g.zoom(Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015)), p.x, p.y);
  }, { passive: false });
  canvas.addEventListener("dblclick", () => g.reset());
  canvas.addEventListener("keydown", (e) => {
    const r = canvas.getBoundingClientRect();
    const map: Record<string, () => void> = {
      ArrowLeft: () => g.key(-1, 0, e.shiftKey), ArrowRight: () => g.key(1, 0, e.shiftKey),
      ArrowUp: () => g.key(0, -1, e.shiftKey), ArrowDown: () => g.key(0, 1, e.shiftKey),
      "+": () => g.zoom(1.2, r.width / 2, r.height / 2), "=": () => g.zoom(1.2, r.width / 2, r.height / 2),
      "-": () => g.zoom(1 / 1.2, r.width / 2, r.height / 2), "0": () => g.reset(),
    };
    if (map[e.key]) { e.preventDefault(); map[e.key](); }
  });
}
