  turtle: ViewTurtle;
  showTurtle: boolean;
  /** faint target drawing of a challenge */
  ghost: Segment[] | null;
}

export interface View {
  readonly canvas: HTMLCanvasElement;
  setScene(s: Scene): void;
  /** Frames the whole drawing. */
  fit(): void;
  /** Back to the default framing (3D: default orientation too). */
  resetView(): void;
  zoomBy(factor: number): void;
  draw(): void;
  /** Re-reads colours/size after a theme or layout change. */
  refresh(): void;
}

export const PAPER = { light: "#fbf9f4", dark: "#fbf9f4" };

export function sizeCanvas(canvas: HTMLCanvasElement) {
  const dpr = window.devicePixelRatio || 1;
  const r = canvas.getBoundingClientRect();
  const w = Math.max(1, Math.round(r.width * dpr)), h = Math.max(1, Math.round(r.height * dpr));
  if (canvas.width !== w || canvas.height !== h) { canvas.width = w; canvas.height = h; }
  return { w: r.width, h: r.height, dpr };
}

/** A "nice" grid step (1, 2, 5 × 10^n) giving roughly `target` pixels at the given scale. */
export function niceStep(scale: number, target = 60) {
  const raw = target / scale;
  const pow = Math.pow(10, Math.floor(Math.log10(raw)));
  const f = raw / pow;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * pow;
}
