import { attachGestures } from "./gestures";
import { niceStep, PAPER, sizeCanvas, type Scene, type View } from "./scene";

const INK = "#2a332f", GRID = "rgba(60,80,70,0.10)", AXIS = "rgba(60,80,70,0.45)";

export class View2D implements View {
  private scene: Scene | null = null;
  private cx = 0; // world point at the canvas centre
  private cy = 0;
  private scale = 1; // pixels per unit
  private raf = 0;

  constructor(readonly canvas: HTMLCanvasElement) {
    attachGestures(canvas, {
      drag: (dx, dy) => { this.cx -= dx / this.scale; this.cy += dy / this.scale; this.request(); },
      pan: (dx, dy) => { this.cx -= dx / this.scale; this.cy += dy / this.scale; this.request(); },
      zoom: (f, x, y) => this.zoomAt(f, x, y),
      key: (dx, dy, shift) => { const s = (shift ? 120 : 40) / this.scale; this.cx += dx * s; this.cy -= dy * s; this.request(); },
      reset: () => this.fit(),
    });
    new ResizeObserver(() => this.request()).observe(canvas);
  }

  setScene(s: Scene) { this.scene = s; this.request(); }
  refresh() { this.request(); }
  zoomBy(f: number) { const r = this.canvas.getBoundingClientRect(); this.zoomAt(f, r.width / 2, r.height / 2); }
  resetView() { this.fit(); }

  private zoomAt(f: number, px: number, py: number) {
    const r = this.canvas.getBoundingClientRect();
    const ns = Math.min(200, Math.max(0.005, this.scale * f));
    // keep the world point under the cursor fixed
    const wx = this.cx + (px - r.width / 2) / this.scale, wy = this.cy - (py - r.height / 2) / this.scale;
    this.scale = ns;
    this.cx = wx - (px - r.width / 2) / ns;
    this.cy = wy + (py - r.height / 2) / ns;
    this.request();
  }

  fit() {
    const r = this.canvas.getBoundingClientRect();
    let x0 = 0, x1 = 0, y0 = 0, y1 = 0;
    const add = (p: number[]) => { x0 = Math.min(x0, p[0]); x1 = Math.max(x1, p[0]); y0 = Math.min(y0, p[1]); y1 = Math.max(y1, p[1]); };
    for (const s of this.scene?.segments ?? []) { add(s.from); add(s.to); }
    for (const s of this.scene?.ghost ?? []) { add(s.from); add(s.to); }
    const w = Math.max(x1 - x0, 1), h = Math.max(y1 - y0, 1);
    const pad = 48;
    const empty = (this.scene?.segments.length ?? 0) === 0 && !this.scene?.ghost?.length;
    this.scale = empty ? 1 : Math.min(8, Math.max(0.005, Math.min((r.width - pad * 2) / w, (r.height - pad * 2) / h)));
    this.cx = empty ? 0 : (x0 + x1) / 2;
    this.cy = empty ? 0 : (y0 + y1) / 2;
    if (empty) this.cy = r.height / 2 / this.scale - 60; // leave room above the origin
    this.request();
  }

  private request() { if (!this.raf) this.raf = requestAnimationFrame(() => { this.raf = 0; this.draw(); }); }

  draw() {
    const { w, h, dpr } = sizeCanvas(this.canvas);
    const ctx = this.canvas.getContext("2d")!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = PAPER.light;
    ctx.fillRect(0, 0, w, h);
    const sx = (x: number) => w / 2 + (x - this.cx) * this.scale;
    const sy = (y: number) => h / 2 - (y - this.cy) * this.scale;

    // grid
    const step = niceStep(this.scale);
    const x0 = this.cx - w / 2 / this.scale, x1 = this.cx + w / 2 / this.scale;
    const y0 = this.cy - h / 2 / this.scale, y1 = this.cy + h / 2 / this.scale;
    ctx.lineWidth = 1;
    ctx.strokeStyle = GRID;
    ctx.beginPath();
    for (let x = Math.ceil(x0 / step) * step; x <= x1; x += step) { ctx.moveTo(Math.round(sx(x)) + 0.5, 0); ctx.lineTo(Math.round(sx(x)) + 0.5, h); }
    for (let y = Math.ceil(y0 / step) * step; y <= y1; y += step) { ctx.moveTo(0, Math.round(sy(y)) + 0.5); ctx.lineTo(w, Math.round(sy(y)) + 0.5); }
    ctx.stroke();

    // axes + origin
    ctx.strokeStyle = AXIS;
    ctx.beginPath();
    ctx.moveTo(0, sy(0)); ctx.lineTo(w, sy(0));
    ctx.moveTo(sx(0), 0); ctx.lineTo(sx(0), h);
    ctx.stroke();
    ctx.font = "11px ui-monospace, monospace";
    ctx.fillStyle = "rgba(60,80,70,0.8)";
    for (let x = Math.ceil(x0 / (step * 2)) * step * 2; x <= x1; x += step * 2) if (Math.abs(x) > 1e-9) ctx.fillText(String(+x.toFixed(6)), sx(x) + 3, Math.min(h - 4, Math.max(12, sy(0) + 13)));
    for (let y = Math.ceil(y0 / (step * 2)) * step * 2; y <= y1; y += step * 2) if (Math.abs(y) > 1e-9) ctx.fillText(String(+y.toFixed(6)), Math.min(w - 30, Math.max(4, sx(0) + 5)), sy(y) - 3);
    ctx.beginPath();
    ctx.arc(sx(0), sy(0), 5, 0, Math.PI * 2);
    ctx.strokeStyle = INK; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = INK;
    ctx.fillText("0", sx(0) + 8, sy(0) + 14);

    const scene = this.scene;
    if (!scene) return;
    ctx.lineCap = "round"; ctx.lineJoin = "round";
    if (scene.ghost?.length) {
      ctx.save();
      ctx.setLineDash([7, 6]);
      ctx.strokeStyle = "rgba(90,100,110,0.55)"; ctx.lineWidth = 3;
      ctx.beginPath();
      for (const s of scene.ghost) { ctx.moveTo(sx(s.from[0]), sy(s.from[1])); ctx.lineTo(sx(s.to[0]), sy(s.to[1])); }
      ctx.stroke();
      ctx.restore();
    }
    // group consecutive segments of the same style into one path
    let key = "";
    ctx.beginPath();
    const flush = () => ctx.stroke();
    for (const s of scene.segments) {
      const k = s.color + s.width;
      if (k !== key) { flush(); ctx.beginPath(); ctx.strokeStyle = s.color; ctx.lineWidth = s.width; key = k; }
      ctx.moveTo(sx(s.from[0]), sy(s.from[1]));
      ctx.lineTo(sx(s.to[0]), sy(s.to[1]));
    }
    flush();

    if (scene.showTurtle) this.turtle(ctx, scene, sx, sy);
  }

  private turtle(ctx: CanvasRenderingContext2D, scene: Scene, sx: (x: number) => number, sy: (y: number) => number) {
    const t = scene.turtle;
    const px = sx(t.pos[0]), py = sy(t.pos[1]);
    const ang = Math.atan2(-t.heading[1], t.heading[0]); // screen angle of the heading
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(ang);
    ctx.beginPath();
    ctx.moveTo(14, 0); ctx.lineTo(-9, 8); ctx.lineTo(-5, 0); ctx.lineTo(-9, -8); ctx.closePath();
    ctx.fillStyle = t.down ? t.color : "rgba(251,249,244,0.9)";
    ctx.strokeStyle = INK; ctx.lineWidth = 1.6; ctx.lineJoin = "round";
    ctx.fill(); ctx.stroke();
    ctx.restore();
  }
}
