    const { w, h, dpr } = sizeCanvas(this.canvas);
    const ctx = this.canvas.getContext("2d")!;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = PAPER.dark;
    ctx.fillRect(0, 0, w, h);
    const { eye, f, right, up } = this.basis();
    const focal = h / 2 / Math.tan(FOV / 2);
    const cam = (p: Vec): Vec => { const d = sub(p, eye); return [dot(d, right), dot(d, up), dot(d, f)]; };
    const scr = (c: Vec): [number, number] => [w / 2 + (c[0] / c[2]) * focal, h / 2 - (c[1] / c[2]) * focal];
    /** Projects a line, clipping it against the near plane; returns null when it is entirely behind the camera. */
    const line = (a: Vec, b: Vec): [number, number, number, number] | null => {
      let ca = cam(a), cb = cam(b);
      if (ca[2] < NEAR && cb[2] < NEAR) return null;
      if (ca[2] < NEAR) ca = lerpNear(ca, cb);
      else if (cb[2] < NEAR) cb = lerpNear(cb, ca);
      const [x0, y0] = scr(ca), [x1, y1] = scr(cb);
      return [x0, y0, x1, y1];
    };
    const stroke = (a: Vec, b: Vec) => { const l = line(a, b); if (l) { ctx.moveTo(l[0], l[1]); ctx.lineTo(l[2], l[3]); } };

    // ground grid sized from the scene extent
    let ext = 100;
    for (const s of this.scene?.segments ?? []) for (const p of [s.from, s.to]) ext = Math.max(ext, Math.abs(p[0]), Math.abs(p[1]));
    for (const s of this.scene?.ghost ?? []) for (const p of [s.from, s.to]) ext = Math.max(ext, Math.abs(p[0]), Math.abs(p[1]));
    const step = niceStep(focal / Math.max(1, this.dist), 56);
    const n = Math.min(40, Math.max(2, Math.ceil(ext / step) + 1));
    const half = n * step;
    ctx.lineWidth = 1;
    ctx.strokeStyle = "rgba(60,80,70,0.16)";
    ctx.beginPath();
    for (let i = -n; i <= n; i++) {
      if (i === 0) continue;
      stroke([i * step, -half, 0], [i * step, half, 0]);
      stroke([-half, i * step, 0], [half, i * step, 0]);
    }
    ctx.stroke();

    // axes: X red, Y green, Z blue
    const axis = (to: Vec, color: string, label: string) => {
      ctx.strokeStyle = color; ctx.lineWidth = 1.8;
      ctx.beginPath(); stroke([0, 0, 0], to); ctx.stroke();
      const l = line([0, 0, 0], to);
      if (l) { ctx.fillStyle = color; ctx.font = "bold 12px ui-monospace, monospace"; ctx.fillText(label, l[2] + 5, l[3] - 4); }
    };
    axis([half, 0, 0], "#c0392b", "X");
    axis([0, half, 0], "#2e9a52", "Y");
    axis([0, 0, half], "#2b6fb3", "Z");
    const o = line([0, 0, 0], [0, 0, 0.001]);
    const oc = cam([0, 0, 0]);
    if (oc[2] > NEAR) { const [ox, oy] = scr(oc); ctx.beginPath(); ctx.arc(ox, oy, 4.5, 0, Math.PI * 2); ctx.strokeStyle = INK; ctx.lineWidth = 1.5; ctx.stroke(); }
    void o;

    const scene = this.scene;
    if (!scene) return;
    ctx.lineCap = "round"; ctx.lineJoin = "round";
    if (scene.ghost?.length) {
      ctx.save();
      ctx.setLineDash([7, 6]); ctx.strokeStyle = "rgba(90,100,110,0.55)"; ctx.lineWidth = 3;
      ctx.beginPath();
      for (const s of scene.ghost) stroke(s.from, s.to);
      ctx.stroke();
      ctx.restore();
    }
    let key = "";
    ctx.beginPath();
    for (const s of scene.segments) {
      const k = s.color + s.width;
      if (k !== key) { ctx.stroke(); ctx.beginPath(); ctx.strokeStyle = s.color; ctx.lineWidth = s.width; key = k; }
      stroke(s.from, s.to);
    }
    ctx.stroke();

    if (scene.showTurtle) {
      // the turtle's own frame: heading (bold), right (red), up (blue), with an arrow head
      const t = scene.turtle;
      const L = this.dist * 0.07;
      const at = (v: Vec, k: number): Vec => [t.pos[0] + v[0] * k, t.pos[1] + v[1] * k, t.pos[2] + v[2] * k];
      const arm = (v: Vec, k: number, color: string, wd: number) => { ctx.strokeStyle = color; ctx.lineWidth = wd; ctx.beginPath(); stroke(t.pos, at(v, k)); ctx.stroke(); };
      arm(t.right, L * 0.45, "#c0392b", 2); arm(t.up, L * 0.45, "#2b6fb3", 2);
      const tip = at(t.heading, L), b1 = at(t.heading, L * 0.55);
      ctx.beginPath();
      stroke(at(t.right, -L * 0.22), tip); stroke(at(t.right, L * 0.22), tip);
      stroke(at(t.right, -L * 0.22), at(t.right, L * 0.22));
      void b1;
      ctx.fillStyle = t.down ? t.color : "rgba(251,249,244,0.9)";
      const c = [at(t.right, -L * 0.22), tip, at(t.right, L * 0.22)].map(cam);
      if (c.every((p) => p[2] > NEAR)) {
        ctx.beginPath();
        c.forEach((p, i) => { const [x, y] = scr(p); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); });
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = INK; ctx.lineWidth = 1.6; ctx.stroke();
      }
    }
  }
}

function lerpNear(behind: Vec, front: Vec): Vec {
  const t = (NEAR - behind[2]) / (front[2] - behind[2]);
  return [behind[0] + (front[0] - behind[0]) * t, behind[1] + (front[1] - behind[1]) * t, NEAR];
}
E
