.brand svg { width: 30px; height: 30px; }
.brand small { font: 12px system-ui; color: var(--muted); font-weight: 400; display: none; }
.nav { display: flex; gap: 4px; margin-left: 8px; flex: 1; flex-wrap: wrap; }
.nav a { padding: 6px 12px; border-radius: 999px; text-decoration: none; color: var(--ink); font-weight: 500; }
.nav a:hover { background: var(--panel2); }
.nav a[aria-current="page"] { background: var(--accent-soft); color: var(--accent); }
.top-actions { display: flex; gap: 6px; }

/* buttons */
.btn { display: inline-flex; align-items: center; gap: 6px; border: 1px solid var(--line); background: var(--panel); border-radius: 9px; padding: 6px 12px; cursor: pointer; min-height: 36px; font-weight: 500; text-decoration: none; color: var(--ink); white-space: nowrap; }
.btn:hover:not(:disabled) { background: var(--panel2); border-color: var(--muted); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.btn.primary:hover:not(:disabled) { filter: brightness(1.08); background: var(--accent); }
.btn.icon { padding: 6px 10px; min-width: 38px; justify-content: center; }
.btn svg { width: 16px; height: 16px; flex: none; }
select.btn { padding-right: 6px; }

/* layout */
main { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.page { max-width: 980px; width: 100%; margin: 0 auto; padding: 22px 18px 60px; }
.page h1 { font-family: var(--display); font-size: 32px; margin: 8px 0 6px; }
.page h2 { font-family: var(--display); font-size: 24px; margin: 34px 0 8px; border-bottom: 1px solid var(--line); padding-bottom: 4px; }
.page .lead { color: var(--muted); max-width: 62ch; }

.ws { display: flex; flex-direction: column; flex: 1; min-height: 0; padding: 10px; gap: 10px; }
.controls { display: flex; flex-wrap: wrap; gap: 8px 12px; align-items: center; background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 8px 10px; box-shadow: var(--shadow); }
.group { display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 9px; overflow: hidden; }
.seg button { border: 0; background: var(--panel); padding: 6px 14px; min-height: 34px; cursor: pointer; font-weight: 600; }
.seg button + button { border-left: 1px solid var(--line); }
.seg button[aria-checked="true"] { background: var(--accent); color: var(--accent-ink); }
.seg button:disabled { opacity: 0.45; cursor: not-allowed; }
.status { color: var(--muted); font-size: 14px; margin-left: auto; min-width: 12ch; text-align: right; }
.status.err { color: var(--danger); }
label.inline { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; color: var(--muted); }
input[type="range"] { accent-color: var(--accent); width: 110px; min-height: 30px; }
.note { font-size: 13px; color: var(--danger); }

.panes { display: grid; grid-template-columns: 1fr; gap: 10px; flex: 1; min-height: 0; }
.pane { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; box-shadow: var(--shadow); display: flex; flex-direction: column; min-height: 0; overflow: hidden; }
.pane-head { display: flex; align-items: center; gap: 6px; padding: 6px 8px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.pane-head h2 { font: 600 13px system-ui; text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); margin: 0 auto 0 4px; }
.view-wrap { position: relative; flex: 1; min-height: 300px; background: #fbf9f4; }
.view-wrap canvas { position: absolute; inset: 0; width: 100%; height: 100%; touch-action: none; display: block; cursor: grab; }
.view-wrap canvas:active { cursor: grabbing; }
.turtle-info { font: 12px var(--mono); color: var(--muted); padding: 5px 10px; border-top: 1px solid var(--line); background: var(--panel2); display: flex; gap: 12px; flex-wrap: wrap; }
@media (min-width: 900px) {
  .panes { grid-template-columns: minmax(340px, 5fr) minmax(380px, 6fr); }
