/* editor */
.editor { position: relative; flex: 1; min-height: 160px; display: flex; font: 14px/21px var(--mono); background: var(--panel); overflow: hidden; }
.ed-gutter { flex: none; overflow: hidden; background: var(--panel2); border-right: 1px solid var(--line); color: var(--muted); text-align: right; user-select: none; padding-top: 8px; }
.ed-gutter-inner .gn { height: 21px; padding: 0 8px 0 10px; }
.gn-run { background: var(--run-line); color: var(--accent); font-weight: 700; }
.gn-err { color: var(--danger); font-weight: 700; background: var(--danger-soft); }
