.ed-wrap { position: relative; flex: 1; overflow: hidden; }
.ed-hl, .ed-input { position: absolute; inset: 0; margin: 0; padding: 8px 12px 8px 10px; border: 0; font: inherit; letter-spacing: 0; tab-size: 2; white-space: pre; word-wrap: normal; overflow-wrap: normal; }
.ed-hl { right: auto; bottom: auto; min-width: 100%; pointer-events: none; color: var(--t-name); }
.ed-hl .ln { height: 21px; white-space: pre; margin: 0 -12px 0 -10px; padding: 0 12px 0 10px; }
.ln-run { background: var(--run-line); box-shadow: inset 3px 0 0 var(--accent); }
.ln-err { background: var(--danger-soft); }
.ed-input { background: transparent; color: transparent; caret-color: var(--ink); resize: none; outline: none; overflow: auto; width: 100%; height: 100%; }
.ed-input::selection { background: rgba(70, 130, 220, 0.35); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px var(--focus); }
.t-cmt { color: var(--t-cmt); font-style: italic; }
.t-num { color: var(--t-num); }
.t-col { color: var(--t-col); box-shadow: inset 0 -3px 0 var(--sw, currentColor); }
.t-bad { color: var(--danger); }
.t-cmd { color: var(--t-cmd); font-weight: 700; }
.t-def { color: var(--t-def); font-weight: 700; }
.t-rep { color: var(--t-rep); font-weight: 700; }
.t-proc { color: var(--t-proc); font-weight: 600; }
.t-br { color: var(--t-br); font-weight: 700; }
.t-par { color: var(--t-br); }
.t-op { color: var(--t-op); }
.t-error { text-decoration: underline wavy var(--danger) 2px; text-underline-offset: 3px; background: rgba(220, 60, 50, 0.18); }
.errbar { padding: 8px 12px; border-top: 1px solid var(--line); background: var(--danger-soft); color: var(--danger); font-size: 14px; display: flex; gap: 8px; align-items: baseline; }
.errbar b { font-family: var(--mono); font-weight: 700; white-space: nowrap; }
.errbar[hidden] { display: none; }

/* challenge panel */
.challenge { padding: 10px 12px; border-bottom: 1px solid var(--line); background: var(--accent-soft); }
.challenge h3 { margin: 0 0 2px; font-family: var(--display); font-size: 19px; }
.challenge p { margin: 4px 0; }
.challenge details { margin: 4px 0; }
.result { margin-top: 6px; padding: 8px 10px; border-radius: 9px; font-weight: 500; }
.result.pass { background: var(--ok); color: #fff; }
.result.fail { background: var(--danger-soft); color: var(--danger); border: 1px solid var(--danger); }

/* cards */
.cards { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 14px; margin-top: 18px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 14px; padding: 14px 16px; box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 8px; }
.card h3 { margin: 0; font-family: var(--display); font-size: 20px; }
.card p { margin: 0; color: var(--muted); flex: 1; }
.badge { display: inline-block; font: 600 11px system-ui; letter-spacing: 0.06em; padding: 2px 8px; border-radius: 999px; background: var(--panel2); border: 1px solid var(--line); color: var(--muted); margin-right: 6px; }
.badge.ok { background: var(--ok); color: #fff; border-color: var(--ok); }

/* reference */
table.ref { width: 100%; border-collapse: collapse; font-size: 14px; display: block; overflow-x: auto; }
table.ref th, table.ref td { text-align: left; vertical-align: top; padding: 8px 10px; border-bottom: 1px solid var(--line); }
