import type { Workspace } from "../app/workspace";
import { CHALLENGES } from "../app/challenges";
import { EXAMPLES } from "../examples";
import { run } from "../lang/interpreter";
import type { Mode, Segment } from "../lang/types";
import { confirmDialog, shareDialog } from "./dialogs";
import { download, h, toast } from "./dom";
import { Editor } from "./editor";
import { icon } from "./icons";
import type { Scene, View } from "./scene";
import { View2D } from "./view2d";
import { View3D } from "./view3d";

const SPEEDS: [number, string][] = [[10, "bardzo wolno"], [40, "wolno"], [150, "średnio"], [500, "szybko"], [2500, "bardzo szybko"], [Infinity, "natychmiast"]];
const SPEED_KEY = "logomocja:speed";

const nextFrame = () => new Promise<void>((res) => { let done = false; const fin = () => { if (!done) { done = true; res(); } }; requestAnimationFrame(() => requestAnimationFrame(fin)); setTimeout(fin, 120); });

export class WorkspaceUI {
  readonly el: HTMLElement;
  private editor: Editor;
  private view2d: View2D;
  private view3d: View3D | null = null;
  private modeBtns: Record<Mode, HTMLButtonElement>;
  private exampleSel: HTMLSelectElement;
  private btnRun: HTMLButtonElement;
  private btnStep: HTMLButtonElement;
  private btnPause: HTMLButtonElement;
  private btnReset: HTMLButtonElement;
  private btnRestore: HTMLButtonElement;
  private statusEl: HTMLElement;
  private errbar: HTMLElement;
  private info: HTMLElement;
  private viewTitle: HTMLElement;
  private btnResetView: HTMLButtonElement;
  private challengeBox: HTMLElement;
  private canvas2d: HTMLCanvasElement;
  private canvas3d: HTMLCanvasElement;
  private note: HTMLElement;
  private autoFit = true;
  private lastCount = -1;
  private ghost: Segment[] | null = null;
  private showGhost = true;
  private threeDReason: string | null = null;

  constructor(private ws: Workspace) {
    const ctrl = ws.controller;
    this.canvas2d = h("canvas", { tabindex: 0, role: "img", "aria-label": "Rysunek 2D. Strzałki przesuwają, plus i minus zmieniają skalę, zero dopasowuje widok." });
    this.canvas3d = h("canvas", { tabindex: 0, role: "img", "aria-label": "Rysunek 3D. Strzałki obracają widok, Shift ze strzałkami przesuwa, plus i minus zmieniają skalę, zero resetuje kamerę.", hidden: true });
    this.view2d = new View2D(this.canvas2d);
    this.view2d.onInteract = () => (this.autoFit = false);
    if (this.canvas3d.getContext("2d")) {
      this.view3d = new View3D(this.canvas3d);
      this.view3d.onInteract = () => (this.autoFit = false);
    } else this.threeDReason = "Tryb 3D jest wyłączony: ta przeglądarka nie udostępnia kontekstu rysowania canvas.";

    // --- controls
    const modeBtn = (m: Mode, label: string) =>
      h("button", { type: "button", role: "radio", "aria-checked": "false", onclick: () => this.chooseMode(m) }, label);
    this.modeBtns = { "2d": modeBtn("2d", "2D"), "3d": modeBtn("3d", "3D") };
    if (!this.view3d) { this.modeBtns["3d"].disabled = true; this.modeBtns["3d"].title = this.threeDReason!; }
    this.exampleSel = h("select", { class: "btn", "aria-label": "Wczytaj przykład", onchange: () => this.pickExample() });
    this.btnRun = this.button("play", "Uruchom", "Uruchom program (Ctrl+Enter)", () => this.run(), "primary", "Control+Enter");
    this.btnStep = this.button("step", "Krok", "Wykonaj jedno polecenie (Alt+K)", () => this.step(), "", "Alt+K");
    this.btnPause = this.button("pause", "Pauza", "Wstrzymaj lub wznów (Alt+P)", () => this.pauseResume(), "", "Alt+P");
    this.btnReset = this.button("reset", "Reset", "Zatrzymaj i wyczyść rysunek (Alt+R)", () => this.reset(), "", "Alt+R");
    const speedVal = Math.min(SPEEDS.length - 1, Math.max(0, Number(localStorage.getItem(SPEED_KEY) ?? 3) || 0));
    const speedText = h("span", {}, "");
    const speed = h("input", { type: "range", min: 0, max: SPEEDS.length - 1, step: 1, value: String(speedVal), "aria-label": "Prędkość animacji" });
    const applySpeed = () => {
      const [ops, name] = SPEEDS[Number(speed.value)];
      ctrl.setSpeed(ops);
      speedText.textContent = name;
      speed.setAttribute("aria-valuetext", name);
      try { localStorage.setItem(SPEED_KEY, speed.value); } catch { /* ignore */ }
    };
    speed.addEventListener("input", applySpeed);
    applySpeed();
    this.statusEl = h("div", { class: "status", role: "status", "aria-live": "polite" });
    this.note = h("div", { class: "note", role: "note" }, this.threeDReason);
    const controls = h("div", { class: "controls", role: "group", "aria-label": "Sterowanie programem" },
      h("div", { class: "seg", role: "radiogroup", "aria-label": "Tryb rysowania" }, this.modeBtns["2d"], this.modeBtns["3d"]),
      this.exampleSel,
      h("div", { class: "group" }, this.btnRun, this.btnStep, this.btnPause, this.btnReset),
      h("label", { class: "inline" }, "Prędkość", speed, speedText),
      this.statusEl,
      this.threeDReason ? this.note : null,
    );

    // --- editor pane
    this.errbar = h("div", { class: "errbar", id: "errbar", role: "alert", hidden: true });
    this.editor = new Editor("errbar");
    this.editor.onInput = (v) => { this.ws.edit(v); };
    this.challengeBox = h("div", { class: "challenge", hidden: true });
    const fileInput = h("input", { type: "file", accept: ".logo,.txt,text/plain", hidden: true, "aria-label": "Otwórz plik .logo", onchange: () => this.openFile(fileInput) });
    this.btnRestore = this.button("undo", "Przywróć szkic", "Przywróć szkic zastąpiony przez przykład lub plik", () => this.restore(), "", undefined, true);
    const editorPane = h("section", { class: "pane", "aria-labelledby": "h-code" },
      h("div", { class: "pane-head" },
        h("h2", { id: "h-code" }, "Kod"),
        this.btnRestore,
        this.button("share", "Udostępnij", "Link do programu", () => this.share()),
        this.button("down", ".logo", "Pobierz program jako plik .logo", () => this.saveFile()),
        this.button("up", "Otwórz", "Otwórz plik .logo", () => fileInput.click()),
        fileInput,
      ),
      this.challengeBox, this.editor.el, this.errbar,
    );

    // --- drawing pane
    this.viewTitle = h("h2", { id: "h-view" }, "Rysunek");
    this.btnResetView = this.button("fit", "Widok", "Zresetuj kamerę", () => { this.autoFit = true; this.active().resetView(); }, "", undefined, true);
    this.info = h("div", { class: "turtle-info", "aria-label": "Stan żółwia" });
    const drawPane = h("section", { class: "pane", "aria-labelledby": "h-view" },
      h("div", { class: "pane-head" },
        this.viewTitle,
        this.iconButton("minus", "Oddal", () => { this.autoFit = false; this.active().zoomBy(1 / 1.25); }),
        this.iconButton("plus", "Przybliż", () => { this.autoFit = false; this.active().zoomBy(1.25); }),
        this.button("fit", "Dopasuj", "Dopasuj widok do rysunku", () => { this.autoFit = true; this.active().fit(); }),
        this.btnResetView,
        this.button("image", "PNG", "Zapisz rysunek jako obraz PNG", () => this.exportPng()),
      ),
      h("div", { class: "view-wrap" }, this.canvas2d, this.canvas3d),
      this.info,
    );

    this.el = h("div", { class: "ws" }, controls, h("div", { class: "panes" }, editorPane, drawPane));
    this.fillExamples();
    ctrl.subscribe(() => this.render());
    this.syncAll();
  }

  // ---- building blocks
  private button(ic: string, label: string, title: string, onclick: () => void, extra = "", keys?: string, hidden = false) {
    return h("button", { class: `btn ${extra}`.trim(), type: "button", title, onclick, "aria-keyshortcuts": keys, hidden }, icon(ic), label);
  }
  private iconButton(ic: string, label: string, onclick: () => void) {
    return h("button", { class: "btn icon", type: "button", title: label, "aria-label": label, onclick }, icon(ic));
  }
  private fillExamples() {
    const sel = this.exampleSel;
    sel.append(h("option", { value: "" }, "Przykłady…"));
    for (const mode of ["2d", "3d"] as Mode[]) {
      const g = h("optgroup", { label: mode === "2d" ? "Płaszczyzna (2D)" : "Przestrzeń (3D)" });
      for (const e of EXAMPLES.filter((x) => x.mode === mode)) g.append(h("option", { value: e.id }, `${e.name} — ${e.blurb}`));
      sel.append(g);
    }
  }

  private active(): View { return this.ws.mode === "3d" && this.view3d ? this.view3d : this.view2d; }

  // ---- visibility and sync
  show() {
    this.el.hidden = false;
    this.syncAll();
  }
  hide() { this.el.hidden = true; }

  /** Pulls everything from the workspace (after a mode switch, example, link or route change). */
  syncAll() {
    const mode = this.ws.mode;
    const inChallenge = this.ws.activeChallenge !== null;
    if (this.editor.value !== this.ws.source) this.editor.setValue(this.ws.source);
    (["2d", "3d"] as Mode[]).forEach((m) => {
      this.modeBtns[m].setAttribute("aria-checked", String(m === mode));
      this.modeBtns[m].tabIndex = m === mode ? 0 : -1;
      if (m === "2d" || this.view3d) this.modeBtns[m].disabled = inChallenge;
    });
    this.canvas2d.hidden = mode === "3d" && !!this.view3d;
    this.canvas3d.hidden = !(mode === "3d" && this.view3d);
    this.btnResetView.hidden = mode !== "3d";
    this.viewTitle.textContent = mode === "3d" ? "Rysunek 3D" : "Rysunek 2D";
    this.btnRestore.hidden = !this.ws.hasBackup;
    this.setupChallenge();
    this.render(true);
    requestAnimationFrame(() => { if (this.autoFit) this.active().fit(); this.active().refresh(); });
  }

  private setupChallenge() {
    const id = this.ws.activeChallenge;
    const box = this.challengeBox;
    box.replaceChildren();
    box.hidden = id === null;
    this.ghost = null;
    if (!id) return;
    const ch = CHALLENGES.find((c) => c.id === id)!;
    this.ghost = run(ch.solution, ch.mode).segments;
    const result = h("div", { role: "status", "aria-live": "polite" });
    const ghostToggle = h("input", { type: "checkbox", checked: this.showGhost, onchange: (e: Event) => { this.showGhost = (e.target as HTMLInputElement).checked; this.render(true); } });
    box.append(
      h("h3", {}, ch.title, " ", h("span", { class: "badge" }, ch.mode.toUpperCase()), this.ws.progress[id]?.solved ? h("span", { class: "badge ok" }, "zaliczone ✓") : null),
      h("p", {}, ch.brief),
