    const live = s.status === "running" || s.status === "paused";
    this.editor.setError(s.error);
    this.editor.setCurrentLine(live ? s.line : null);
    this.errbar.hidden = !s.error;
    if (s.error) {
      this.errbar.replaceChildren(h("b", {}, `Wiersz ${s.error.line}, kolumna ${s.error.column}`), s.error.message);
    }
    const n = s.segments.length;
    const text: Record<string, string> = {
      idle: "Gotowy", running: "Rysuję…", paused: s.line ? `Wstrzymano (wiersz ${s.line})` : "Wstrzymano",
      finished: `Gotowe: ${n} ${n === 1 ? "odcinek" : "odcinków"}`, error: "Błąd w programie",
    };
    this.statusEl.textContent = text[s.status];
    this.statusEl.classList.toggle("err", s.status === "error");
    this.btnRun.disabled = s.status === "running";
    this.btnStep.disabled = false;
    this.btnPause.disabled = !live;
    this.btnPause.lastChild!.textContent = s.status === "paused" ? "Wznów" : "Pauza";
    this.btnReset.disabled = s.status === "idle" && n === 0;
    this.btnRestore.hidden = !this.ws.hasBackup;
    const scene: Scene = { segments: s.segments, turtle: s.turtle, showTurtle: true, ghost: this.showGhost ? this.ghost : null };
    this.view2d.setScene(scene);
    this.view3d?.setScene(scene);
    if (this.autoFit && (force || n !== this.lastCount)) this.active().fit();
    this.lastCount = n;
    const p = s.turtle.pos.map((v) => +v.toFixed(2));
    const heading = Math.round(((Math.atan2(s.turtle.heading[0], s.turtle.heading[1]) * 180) / Math.PI + 360) % 360);
    this.info.textContent = this.ws.mode === "3d"
      ? `x ${p[0]}  y ${p[1]}  z ${p[2]}  ·  pióro ${s.turtle.down ? "opuszczone" : "podniesione"}`
      : `x ${p[0]}  y ${p[1]}  ·  kierunek ${heading}°  ·  pióro ${s.turtle.down ? "opuszczone" : "podniesione"}`;
    const label = `Rysunek ${this.ws.mode.toUpperCase()}: ${n} odcinków. ${this.info.textContent}`;
    (this.ws.mode === "3d" ? this.canvas3d : this.canvas2d).setAttribute("aria-description", label);
  }
}
