import { Workspace } from "./app/workspace";
import { run } from "./lang/interpreter";
import type { Mode } from "./lang/types";
import { shortcutsDialog } from "./ui/dialogs";
import { clear, h } from "./ui/dom";
import { icon, TURTLE_LOGO } from "./ui/icons";
import { challengesPage, referencePage } from "./ui/pages";
import { applyTheme, loadTheme, nextTheme, THEME_LABEL, type Theme } from "./ui/theme";
import { WorkspaceUI } from "./ui/workspace-ui";

export const VERSION = "1.0.0";

function boot() {
  const root = document.getElementById("app")!;
  let theme: Theme = loadTheme();
  applyTheme(theme);

  let storage: Storage;
  try { storage = window.localStorage; storage.getItem("x"); } catch { storage = memoryStorage(); }
  const ws = new Workspace(storage);
  const wsui = new WorkspaceUI(ws);
  const page = h("div", { id: "page" });

  const themeBtn = h("button", { class: "btn", type: "button", onclick: () => {
    theme = nextTheme(theme);
    applyTheme(theme);
    themeBtn.lastChild!.textContent = THEME_LABEL[theme];
    wsui.syncAll();
  } }, icon("theme"), THEME_LABEL[theme]);
  const nav = h("nav", { class: "nav", "aria-label": "Główna nawigacja" },
    ...[["#/", "Pracownia", "workspace"], ["#/wyzwania", "Wyzwania", "challenges"], ["#/instrukcja", "Instrukcja", "reference"]].map(([href, label, key]) =>
      h("a", { href, "data-route": key }, label)));
  const header = h("header", { class: "top" },
    h("a", { class: "brand", href: "#/", "aria-label": "Logomocja — strona główna" }, Object.assign(h("span", {}), { innerHTML: TURTLE_LOGO }), "Logomocja"),
    nav,
    h("div", { class: "top-actions" },
      h("button", { class: "btn", type: "button", onclick: shortcutsDialog, "aria-label": "Skróty klawiszowe", title: "Skróty klawiszowe" }, icon("keys"), "Skróty"),
      themeBtn),
  );
  const main = h("main", { id: "main", tabindex: -1 }, wsui.el, page);
  root.append(h("a", { class: "skip", href: "#main", onclick: (e: Event) => { e.preventDefault(); main.focus(); } }, "Przejdź do treści"), header, main);

  const setCurrent = (key: string) => nav.querySelectorAll("a").forEach((a) => {
    if (a.dataset.route === key) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
  });

  function route() {
    const hash = location.hash || "#/";
    const [path] = hash.slice(1).split("?");
    if (/[?&]tryb=/.test(hash)) {
      if (ws.openPermalink(hash)) history.replaceState(null, "", location.pathname + location.search + "#/");
      else history.replaceState(null, "", location.pathname + location.search + "#/");
    }
    const challenge = path.match(/^\/wyzwanie\/([\w-]+)$/);
    if (challenge && ws.openChallenge(challenge[1]) !== false && ws.activeChallenge) {
      page.hidden = true; clear(page); wsui.show(); setCurrent("challenges");
    } else if (path === "/wyzwania") {
      wsui.hide(); page.hidden = false; clear(page); page.append(challengesPage(ws)); setCurrent("challenges");
    } else if (path === "/instrukcja") {
      wsui.hide(); page.hidden = false; clear(page);
      page.append(referencePage(async (code, mode) => {
        if (await wsui.loadSnippet(code, mode)) { location.hash = "#/"; }
      }));
      setCurrent("reference");
    } else {
      if (ws.activeChallenge) ws.leaveChallenge();
      page.hidden = true; clear(page); wsui.show(); setCurrent("workspace");
    }
    window.scrollTo(0, 0);
  }
  window.addEventListener("hashchange", route);

  document.addEventListener("keydown", (e) => {
    if (wsui.el.hidden) return;
    const c = ws.controller;
    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") { e.preventDefault(); wsui.run(); }
    else if (e.altKey && e.code === "KeyK") { e.preventDefault(); wsui.step(); }
    else if (e.altKey && e.code === "KeyP") { e.preventDefault(); wsui.pauseResume(); }
    else if (e.altKey && e.code === "KeyR") { e.preventDefault(); wsui.reset(); }
    void c;
  });

  const startedWithLink = /[?&]tryb=/.test(location.hash);
  route();
  if (!startedWithLink) ws.controller.runToEnd();

  (window as any).logomocja = {
    version: VERSION,
    run: (source: string, mode: Mode) => run(source, mode),
    open: (source: string, mode: Mode) => {
      location.hash.startsWith("#/wyzwa") || location.hash.startsWith("#/instr") ? (location.hash = "#/") : 0;
      return wsui.open(source, mode);
    },
  };
}

function memoryStorage(): Storage {
  const m = new Map<string, string>();
  return { getItem: (k) => m.get(k) ?? null, setItem: (k, v) => void m.set(k, v), removeItem: (k) => void m.delete(k), clear: () => m.clear(), key: (i) => [...m.keys()][i] ?? null, get length() { return m.size; } } as Storage;
}

boot();
