import { Window } from "/tmp/smoke/node_modules/happy-dom";
const win = new Window({ url: "http://localhost/" });
Object.assign(globalThis, { window: win, document: win.document, requestAnimationFrame: (f: any) => { f(0); return 1; }, ResizeObserver: class { observe() {} } });
(win as any).devicePixelRatio = 1;
const { View2D } = await import("/work/src/ui/view2d.ts");
const { View3D } = await import("/work/src/ui/view3d.ts");
const { EXAMPLES } = await import("/work/src/examples.ts");
const { run } = await import("/work/src/lang/interpreter.ts");

const W = 800, H = 600;
function makeCanvas() {
  const calls: number[][] = [];
  const ctx: any = new Proxy({}, { get: (_t, k) => {
    if (k === "moveTo" || k === "lineTo") return (x: number, y: number) => calls.push([x, y]);
    if (k === "measureText") return () => ({ width: 5 });
    return () => {};
  }, set: () => true });
  const c: any = win.document.createElement("canvas");
  c.getContext = () => ctx; c.getBoundingClientRect = () => ({ width: W, height: H, left: 0, top: 0 });
  return { c, calls };
}
const turtle = { pos: [0, 0, 0], heading: [0, 1, 0], right: [1, 0, 0], up: [0, 0, 1], down: true, color: "#16866a" };
let bad = 0;
for (const ex of EXAMPLES) {
  const segs = run(ex.source, ex.mode).segments;
  const { c, calls } = makeCanvas();
  const v: any = ex.mode === "2d" ? new View2D(c) : new View3D(c);
  v.setScene({ segments: segs, turtle: { ...turtle }, showTurtle: true, ghost: null });
