// Static preview of dist/ mounted at BASE_PATH (default "/"). Usage: BASE_PATH=/x/ bun run serve.ts [port]
const base = (process.env.BASE_PATH ?? "/").replace(/\/?$/, "/");
const port = Number(process.argv[2] ?? process.env.PORT ?? 4173);
const server = Bun.serve({
  port,
  async fetch(req) {
    const path = decodeURIComponent(new URL(req.url).pathname);
    if (!path.startsWith(base)) return new Response("Not found", { status: 404 });
    const rel = path.slice(base.length) || "index.html";
    if (rel.includes("..")) return new Response("Bad request", { status: 400 });
    const file = Bun.file(`dist/${rel}`);
    return (await file.exists()) ? new Response(file) : new Response("Not found", { status: 404 });
  },
});
console.log(`http://localhost:${server.port}${base}`);
